import React from 'react';

import Spacings from '@dynatrace/strato-design-tokens/spacings';

import { formattedTimeframe } from './TimeFrameHeader.sty.js';
import { FormattedTimeframe } from '../../../../../../../formatters/timeframe/FormattedTimeframe.js';
import { DurationChipAtom } from '../../../../tooltip-atoms/components/DurationChipAtom.js';
import { TooltipItem } from '../../../section-components/TooltipItem.js';

export interface TimeFrameHeaderProps {
  from: Date;
  to: Date;
  showDuration?: boolean;
}

export const TimeFrameHeader = ({
  from,
  to,
  showDuration,
}: TimeFrameHeaderProps) => {
  return (
    <TooltipItem style={{ padding: `0 ${Spacings.Size2}` }}>
      {showDuration && (
        <DurationChipAtom
          from={from}
          to={to}
          style={{ marginRight: Spacings.Size4 }}
        />
      )}

      <FormattedTimeframe from={from} to={to} className={formattedTimeframe} />
    </TooltipItem>
  );
};

TimeFrameHeader['displayName'] = 'ChartTooltip.TimeFrameHeader';
